/** "panel" = old behavior, opens a React portfolio panel over the hub.
 *  "dungeon" = new behavior, fades into a dedicated Scene (see targetScene).
 *  Zones are migrated from panel -> dungeon one at a time; see the phased
 *  plan. Contact was migrated first (game/scenes/ContactDungeonScene.ts). */
export type ZoneKind = 'panel' | 'dungeon';

export interface ZoneDef {
  id: LocationId;
  tileX: number;
  tileY: number;
  radius: number; // interaction radius in pixels
  kind: ZoneKind;
  /** Phaser scene key to fade into. Required when kind === 'dungeon'. */
  targetScene?: string;
}

export const zoneDefs: ZoneDef[] = [
  { id: 'about', tileX: 22, tileY: 5, radius: 46, kind: 'panel' },
  { id: 'experience', tileX: 7, tileY: 14, radius: 46, kind: 'panel' },
  { id: 'skills', tileX: 38, tileY: 14, radius: 46, kind: 'panel' },
  { id: 'contact', tileX: 10, tileY: 25, radius: 46, kind: 'dungeon', targetScene: 'contact-dungeon' },
  { id: 'projects', tileX: 35, tileY: 25, radius: 46, kind: 'dungeon', targetScene: 'projects-dungeon' }
];

